namespace Anchal.Domain.CommissionerMonitoring;

public enum MonitoringActivityKind { Service = 1, Complaint = 2, FieldTask = 3 }
public sealed class MonitoringUser { public Guid Id { get; set; } public string LoginName { get; set; } = string.Empty; public string NormalizedLoginName { get; set; } = string.Empty; public string PasswordHash { get; set; } = string.Empty; public string DisplayName { get; set; } = string.Empty; public string Role { get; set; } = string.Empty; public bool IsActive { get; set; } = true; public DateTimeOffset CreatedAt { get; set; } public ICollection<MonitoringUserOffice> OfficeAssignments { get; set; } = new List<MonitoringUserOffice>(); }
public sealed class MonitoringOffice { public Guid Id { get; set; } public string Code { get; set; } = string.Empty; public string Name { get; set; } = string.Empty; public bool IsActive { get; set; } = true; public ICollection<MonitoringUserOffice> UserAssignments { get; set; } = new List<MonitoringUserOffice>(); }
public sealed class MonitoringUserOffice { public Guid UserId { get; set; } public MonitoringUser User { get; set; } = null!; public Guid OfficeId { get; set; } public MonitoringOffice Office { get; set; } = null!; public DateTimeOffset AssignedAt { get; set; } }
public sealed class MonitoringCatalogItem { public Guid Id { get; set; } public MonitoringActivityKind Kind { get; set; } public string Key { get; set; } = string.Empty; public string Name { get; set; } = string.Empty; public int SortOrder { get; set; } public bool IsActive { get; set; } = true; }
public sealed class MonitoringOfficeSetup { public Guid Id { get; set; } public Guid OfficeId { get; set; } public MonitoringOffice Office { get; set; } = null!; public Guid LockedByUserId { get; set; } public MonitoringUser LockedByUser { get; set; } = null!; public DateOnly EffectiveDate { get; set; } public DateTimeOffset LockedAt { get; set; } public ICollection<MonitoringOpeningBalance> OpeningBalances { get; set; } = new List<MonitoringOpeningBalance>(); }
public sealed class MonitoringOpeningBalance { public Guid Id { get; set; } public Guid OfficeSetupId { get; set; } public MonitoringOfficeSetup OfficeSetup { get; set; } = null!; public MonitoringActivityKind Kind { get; set; } public string ItemKey { get; set; } = string.Empty; public int Count { get; set; } }
public sealed class MonitoringReport { public Guid Id { get; set; } public Guid OfficeId { get; set; } public MonitoringOffice Office { get; set; } = null!; public DateOnly ReportingDate { get; set; } public bool IsZeroActivity { get; set; } public Guid SubmittedByUserId { get; set; } public MonitoringUser SubmittedByUser { get; set; } = null!; public DateTimeOffset SubmittedAt { get; set; } public DateTimeOffset UpdatedAt { get; set; } public ICollection<MonitoringReportEntry> Entries { get; set; } = new List<MonitoringReportEntry>(); }
public sealed class MonitoringReportEntry { public Guid Id { get; set; } public Guid ReportId { get; set; } public MonitoringReport Report { get; set; } = null!; public MonitoringActivityKind Kind { get; set; } public string ItemKey { get; set; } = string.Empty; public int ReceivedCount { get; set; } public int DisposedCount { get; set; } public int ClosingBalance { get; set; } }
public sealed class MonitoringCorrection { public Guid Id { get; set; } public Guid ReportId { get; set; } public MonitoringReport Report { get; set; } = null!; public Guid? EntryId { get; set; } public MonitoringReportEntry? Entry { get; set; } public Guid CorrectedByUserId { get; set; } public MonitoringUser CorrectedByUser { get; set; } = null!; public string Reason { get; set; } = string.Empty; public string BeforeJson { get; set; } = "{}"; public string AfterJson { get; set; } = "{}"; public DateTimeOffset CorrectedAt { get; set; } }
public sealed class MonitoringAuditEvent { public Guid Id { get; set; } public Guid OfficeId { get; set; } public MonitoringOffice Office { get; set; } = null!; public Guid? ActorUserId { get; set; } public MonitoringUser? ActorUser { get; set; } public string AggregateType { get; set; } = string.Empty; public Guid AggregateId { get; set; } public string Action { get; set; } = string.Empty; public string BeforeJson { get; set; } = "{}"; public string AfterJson { get; set; } = "{}"; public DateTimeOffset OccurredAt { get; set; } }
